package org.sleepwell.app;
import java.time.*;import org.junit.Test;import static org.junit.Assert.*;
public final class SunriseMathTest {
    final ZoneId ny=ZoneId.of("America/New_York");
    void reference(String date,String utc){Long actual=SunriseMath.at(LocalDate.parse(date),40.72,-74.02,ny);assertNotNull(actual);assertTrue(date+" expected within 3 min of NOAA daily table, actual "+Instant.ofEpochMilli(actual),Math.abs(actual-Instant.parse(utc).toEpochMilli())<=180000);assertEquals(0,actual%60000);}
    @Test public void winterAndSummerMatchIndependentNoaaTableWithinThreeMinutes(){reference("2026-01-01","2026-01-01T12:20:00Z");reference("2026-06-01","2026-06-01T09:27:00Z");reference("2026-10-25","2026-10-25T11:18:00Z");}
    @Test public void realInstantRemainsContinuousAcrossSpringAndAutumnDst(){reference("2026-03-07","2026-03-07T11:21:00Z");reference("2026-03-08","2026-03-08T11:19:00Z");reference("2026-11-01","2026-11-01T11:26:00Z");}
    @Test public void dateLineCandidatesBelongToRequestedLocalDate(){for(ZoneId zone:new ZoneId[]{ZoneId.of("Pacific/Kiritimati"),ZoneId.of("Pacific/Pago_Pago")})for(String date:new String[]{"2026-01-01","2026-06-21","2026-12-31"}){LocalDate day=LocalDate.parse(date);Long result=SunriseMath.at(day,0,zone.getId().contains("Kiritimati")?-157.4:-170.7,zone);assertNotNull(result);assertEquals(day,Instant.ofEpochMilli(result).atZone(zone).toLocalDate());}}
    @Test public void polarDayNightAndExactPolesAreUnavailable(){for(String date:new String[]{"2026-06-21","2026-12-21"}){assertNull(SunriseMath.at(LocalDate.parse(date),69.65,18.96,ZoneId.of("Europe/Oslo")));assertNull(SunriseMath.at(LocalDate.parse(date),90,0,ZoneOffset.UTC));assertNull(SunriseMath.at(LocalDate.parse(date),-90,0,ZoneOffset.UTC));}}
    @Test public void leapYearAndSupportedYearBoundariesAreDeterministic(){for(String date:new String[]{"2000-02-29","2024-02-29","2100-12-31"}){LocalDate day=LocalDate.parse(date);assertNotNull(SunriseMath.at(day,24.71,46.67,ZoneId.of("Asia/Riyadh")));assertEquals(SunriseMath.at(day,24.71,46.67,ny),SunriseMath.at(day,24.71,46.67,ny));}assertNull(SunriseMath.at(LocalDate.parse("1999-12-31"),0,0,ny));assertNull(SunriseMath.at(LocalDate.parse("2101-01-01"),0,0,ny));}
    @Test public void invalidCoordinatesCannotBecomeEquatorialDefaults(){for(double latitude:new double[]{Double.NaN,Double.POSITIVE_INFINITY,-90.1,90.1})assertThrows(IllegalArgumentException.class,()->SunriseMath.at(LocalDate.of(2026,1,1),latitude,0,ny));for(double longitude:new double[]{Double.NaN,Double.NEGATIVE_INFINITY,-180.1,180.1})assertThrows(IllegalArgumentException.class,()->SunriseMath.at(LocalDate.of(2026,1,1),0,longitude,ny));}
}
